function formatRemaining(currentTime, duration) {
	const remaining = Math.max(0, Math.floor((duration - currentTime) / 60));
	if (remaining <= 1) return "1m left";
	if (remaining >= 60) return `${Math.floor(remaining / 60)}h ${remaining % 60}m left`;
	return `${remaining}m left`;
}
function isInCinemas(releaseDate) {
	if (!releaseDate) return false;
	const ts = Date.parse(releaseDate);
	if (!Number.isFinite(ts)) return false;
	const diffDays = (Date.now() - ts) / 864e5;
	return diffDays >= -14 && diffDays <= 75;
}
